// The app's signatures and pairing proofs must be byte-identical to the
// Rust implementation (rp-policy). Fixtures generated by rp-probe.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:rp_console/core/auth/admin_key.dart';
import 'package:rp_console/core/pairing/pairing.dart';

void main() {
  final fx = jsonDecode(File('../../test/fixtures/console/crypto.json').readAsStringSync()) as Map<String, dynamic>;

  test('admin key, id and Ed25519 signature match rp-policy', () async {
    final key = await AdminKey.fromSeed(hexDecode(fx['private_key_hex'] as String));
    expect(key.publicKeyB64, fx['public_key_b64']);
    expect(key.adminId, fx['admin_id']);
    final env = fx['envelope'] as Map<String, dynamic>;
    final s = await key.signAt(
      fx['device_id'] as String,
      env['payload'] as String,
      env['nonce'] as String,
      env['expires_at'] as int,
    );
    expect(s.toJson(), env);
  });

  test('pairing proofs match rp-policy', () async {
    final p = fx['pairing'] as Map<String, dynamic>;
    final secret = hexDecode(p['secret'] as String);
    expect(
      await hmacHex(
        secret,
        clientMessage(fx['device_id'] as String, p['public_key'] as String, p['client_nonce'] as String),
      ),
      p['client_proof'],
    );
    expect(
      await hmacHex(
        secret,
        serverMessage(
          fx['device_id'] as String,
          p['public_key'] as String,
          p['client_nonce'] as String,
          p['cert_sha256'] as String,
          p['admin_id'] as String,
        ),
      ),
      p['server_proof'],
    );
  });

  test('signing covers device, nonce, expiry and payload', () async {
    final key = await AdminKey.fromSeed(List.filled(32, 7));
    final a = await key.signAt('d1', '{"op":"x"}', '00' * 16, 100);
    for (final b in [
      await key.signAt('d2', '{"op":"x"}', '00' * 16, 100),
      await key.signAt('d1', '{"op":"y"}', '00' * 16, 100),
      await key.signAt('d1', '{"op":"x"}', '01' * 16, 100),
      await key.signAt('d1', '{"op":"x"}', '00' * 16, 101),
    ]) {
      expect(b.signature, isNot(a.signature));
    }
  });

  test('fresh requests use random nonces and expire within 60 s', () async {
    final (key, seed) = await AdminKey.generate();
    expect(seed.length, 32);
    final now = DateTime.now();
    final a = await key.sign('d', {'op': 'session'}, now: now);
    final b = await key.sign('d', {'op': 'session'}, now: now);
    expect(a.nonce, isNot(b.nonce));
    expect(a.nonce, matches(RegExp(r'^[0-9a-f]{32}$')));
    expect(a.expiresAt - now.millisecondsSinceEpoch ~/ 1000, inInclusiveRange(59, 60));
    expect(jsonDecode(a.payload), {'op': 'session'});
  });

  test('hex helpers', () {
    expect(hexOf([0, 15, 255]), '000fff');
    expect(hexDecode('000fff'), [0, 15, 255]);
    expect(() => hexDecode('0'), throwsFormatException);
    expect(() => hexDecode('zz'), throwsFormatException);
    expect(sameHex('ABCD', 'abcd'), isTrue);
    expect(sameHex('abcd', 'abce'), isFalse);
    expect(sameHex('ab', 'abcd'), isFalse);
  });
}
